CREATE TABLE public.food_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, log_date date NOT NULL DEFAULT current_date, meal text NOT NULL DEFAULT 'snack', name text NOT NULL, calories integer NOT NULL DEFAULT 0, protein_g numeric NOT NULL DEFAULT 0, carbs_g numeric NOT NULL DEFAULT 0, fat_g numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.water_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, log_date date NOT NULL DEFAULT current_date, ml integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.body_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, measured_on date NOT NULL DEFAULT current_date, weight_kg numeric, waist_cm numeric, body_fat_pct numeric, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.nutrition_targets (member_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, calories integer, protein_g integer, carbs_g integer, fat_g integer, water_ml integer DEFAULT 2500, set_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON public.food_logs(member_id, log_date);
CREATE INDEX ON public.water_logs(member_id, log_date);
CREATE INDEX ON public.body_measurements(member_id, measured_on);
CREATE OR REPLACE FUNCTION public.validate_food_meal() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.meal NOT IN ('breakfast','lunch','dinner','snack') THEN RAISE EXCEPTION 'invalid meal'; END IF; IF NEW.calories < 0 OR NEW.calories > 10000 THEN RAISE EXCEPTION 'invalid calories'; END IF; RETURN NEW; END $$;
CREATE TRIGGER food_logs_validate BEFORE INSERT OR UPDATE ON public.food_logs FOR EACH ROW EXECUTE FUNCTION public.validate_food_meal();
GRANT SELECT, INSERT, UPDATE, DELETE ON public.food_logs, public.water_logs, public.body_measurements, public.nutrition_targets TO authenticated;
GRANT ALL ON public.food_logs, public.water_logs, public.body_measurements, public.nutrition_targets TO service_role;
ALTER TABLE public.food_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.water_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.body_measurements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nutrition_targets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "food read" ON public.food_logs FOR SELECT TO authenticated USING (member_id = auth.uid() OR public.is_admin(auth.uid()) OR public.manages_member(auth.uid(), member_id));
CREATE POLICY "food own insert" ON public.food_logs FOR INSERT TO authenticated WITH CHECK (member_id = auth.uid());
CREATE POLICY "food own update" ON public.food_logs FOR UPDATE TO authenticated USING (member_id = auth.uid()) WITH CHECK (member_id = auth.uid());
CREATE POLICY "food own delete" ON public.food_logs FOR DELETE TO authenticated USING (member_id = auth.uid());
CREATE POLICY "water read" ON public.water_logs FOR SELECT TO authenticated USING (member_id = auth.uid() OR public.is_admin(auth.uid()) OR public.manages_member(auth.uid(), member_id));
CREATE POLICY "water own insert" ON public.water_logs FOR INSERT TO authenticated WITH CHECK (member_id = auth.uid());
CREATE POLICY "water own delete" ON public.water_logs FOR DELETE TO authenticated USING (member_id = auth.uid());
CREATE POLICY "body read" ON public.body_measurements FOR SELECT TO authenticated USING (member_id = auth.uid() OR public.is_admin(auth.uid()) OR public.manages_member(auth.uid(), member_id));
CREATE POLICY "body own insert" ON public.body_measurements FOR INSERT TO authenticated WITH CHECK (member_id = auth.uid());
CREATE POLICY "body own update" ON public.body_measurements FOR UPDATE TO authenticated USING (member_id = auth.uid()) WITH CHECK (member_id = auth.uid());
CREATE POLICY "body own delete" ON public.body_measurements FOR DELETE TO authenticated USING (member_id = auth.uid());
CREATE POLICY "targets read" ON public.nutrition_targets FOR SELECT TO authenticated USING (member_id = auth.uid() OR public.is_admin(auth.uid()) OR public.manages_member(auth.uid(), member_id));
CREATE POLICY "targets write" ON public.nutrition_targets FOR ALL TO authenticated USING (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.coach_assignments c WHERE c.coach_id = auth.uid() AND c.member_id = nutrition_targets.member_id AND c.active)) WITH CHECK (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.coach_assignments c WHERE c.coach_id = auth.uid() AND c.member_id = nutrition_targets.member_id AND c.active));
CREATE TRIGGER nutrition_targets_updated BEFORE UPDATE ON public.nutrition_targets FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();